import{_ as a,C as i,c as l,o as c,a3 as o,G as n,j as s,a as r}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Create an invoice","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/customer-invoices/create-invoice.md","filePath":"master/finance/customer-invoices/create-invoice.md","lastUpdated":1791902625000}'),h={name:"master/finance/customer-invoices/create-invoice.md"};function g(d,e,m,u,p,v){const t=i("ImagePopup");return c(),l("div",null,[e[0]||(e[0]=o('<h1 id="create-an-invoice" tabindex="-1">Create an invoice <a class="header-anchor" href="#create-an-invoice" aria-label="Permalink to &quot;Create an invoice&quot;">​</a></h1><p>An invoice asks a customer to pay for what you sold. It lists the products, the taxes and the total, and it states the date the money is due. When you confirm it, Aureus also writes the matching accounting entry, so your reports stay correct without extra work.</p><blockquote><p><strong>In simple words:</strong> You fill in a form, click <strong>Confirm</strong>, and the invoice becomes official. Then you send it and wait for the payment.</p></blockquote><p>You use invoices every time you sell something and want to be paid. If the sale started in the <strong>Sales</strong> app, create the invoice from the order instead. See <a href="./../../sales/sales/invoicing/order-to-invoice.html">Order to invoice</a>.</p><p>Open the invoice list with <code>Invoices → Customers → Invoices</code> or <code>Accounting → Customers → Invoices</code>. Both apps show the same screen.</p><p>In this page we use one example. The customer <strong>Azure Interiors</strong> buys 4 Camping Hammocks and must pay in 30 days.</p><h2 id="the-invoice-list" tabindex="-1">The invoice list <a class="header-anchor" href="#the-invoice-list" aria-label="Permalink to &quot;The invoice list&quot;">​</a></h2><p>The list shows every invoice, newest first.</p>',8)),n(t,{src:"/images1/finance/invoice_list.png",alt:"Invoices list with the view tabs, Export, Group by, search box and the Summary row at the bottom"}),e[1]||(e[1]=o('<h3 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h3><p>The tabs above the list are ready-made views:</p><ul><li><strong><em>Default:</em></strong> All invoices.</li><li><strong><em>Draft</em>, <em>Posted</em>, <em>Cancelled</em>:</strong> Invoices in that state.</li><li><strong><em>Not Secured</em>:</strong> Invoices that have no security hash saved.</li><li><strong><em>To Check</em>:</strong> Posted invoices that nobody has marked as checked.</li><li><strong><em>To Pay</em>:</strong> Posted invoices that still wait for payment.</li><li><strong><em>Unpaid</em>:</strong> Posted invoices with an <strong>Amount Due</strong> above zero.</li><li><strong><em>In Payment</em>:</strong> Posted invoices with the payment state <strong>In payment</strong>.</li><li><strong><em>Overdue</em>:</strong> Not paid invoices whose due date is in the past.</li></ul><p>If you cannot see all the tabs, click the three dots at the end of the tab bar.</p><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><p>The list shows <strong>Number</strong>, <strong>State</strong>, <strong>Created By</strong>, <strong>Customer</strong>, <strong>Invoice Date</strong>, <strong>Due Date</strong>, <strong>Tax Excluded</strong>, <strong>Tax</strong>, <strong>Total</strong>, <strong>Amount Due</strong> and <strong>Payment State</strong>. A summary row adds up the amounts you see.</p><p>Use the column toggle to show more: <strong>Checked</strong>, <strong>Accounting</strong>, <strong>Source Document</strong>, <strong>Reference</strong>, <strong>Sales Person</strong> and <strong>Invoice Currency</strong>.</p><h3 id="search-filter-group-and-export" tabindex="-1">Search, filter, group and export <a class="header-anchor" href="#search-filter-group-and-export" aria-label="Permalink to &quot;Search, filter, group and export&quot;">​</a></h3><ul><li>Type in the search box to find an invoice.</li><li>Use the filter icon to build rules on fields such as <strong>Number</strong>, <strong>Customer</strong>, <strong>Invoice Date</strong>, <strong>Journal</strong>, <strong>Currency</strong>, <strong>Total Amount</strong> or <strong>Amount Due</strong>.</li><li>Use <strong>Group by</strong> to fold the list by <strong>Customer</strong>, <strong>Invoice Date</strong>, <strong>Sales Person</strong>, <strong>Currency</strong> and more.</li><li>Click <strong>Export</strong> to download the rows you see.</li></ul><p>See <a href="./../../getting-started/search-filter-group.html">Search, filter and group records</a>.</p><h2 id="create-an-invoice-1" tabindex="-1">Create an invoice <a class="header-anchor" href="#create-an-invoice-1" aria-label="Permalink to &quot;Create an invoice&quot;">​</a></h2><ol><li>Go to <code>Invoices → Customers → Invoices</code> or <code>Accounting → Customers → Invoices</code>.</li><li>Click <strong>New Invoice</strong>.</li><li>Fill in the <strong>General</strong> section and the <strong>Invoice Lines</strong> tab.</li><li>Click <strong>Create</strong>. Use <strong>Create &amp; create another</strong> to save and open an empty form.</li></ol>',12)),n(t,{src:"/images1/finance/invoice_create_empty.png",alt:"New Invoice page with the State bar (Draft, Posted) and the General section empty"}),e[2]||(e[2]=o('<p>The state bar at the top shows <strong>Draft</strong> and <strong>Posted</strong>. A new invoice is a <strong>Draft</strong>.</p><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Customer:</em></strong> Who you invoice. Required. Pick an existing customer. To add one, see <a href="./../../getting-started/contacts/contacts.html">Contacts</a>. This also fills <strong>Sales Person</strong>, <strong>Payment Term</strong>, <strong>Payment Method</strong> and the <strong>Recipient Bank</strong> from the customer record.</li><li><strong><em>Invoice Date:</em></strong> The date on the invoice. It starts as today. If you leave it empty, Aureus uses the day you confirm.</li><li><strong><em>Due Date:</em></strong> The last day to pay. Required. It is hidden when you choose a <strong>Payment Term</strong>, because the term then works out the date.</li><li><strong><em>Payment Term:</em></strong> The rule for when to pay, such as 30 Days. Pick one when you want Aureus to calculate the due date. See <a href="./payment-terms.html">Payment terms</a>.</li><li><strong><em>Journal:</em></strong> The accounting book where the invoice is recorded. Required. Only sales journals are listed, normally <strong>Customer Invoices</strong>.</li><li><strong><em>Currency:</em></strong> The currency of the invoice. Required. It starts as the currency of your company.</li></ul><p><strong>Example:</strong> Choose <strong>Azure Interiors</strong>. Pick <strong>30 Days</strong> as <strong>Payment Term</strong>. Keep the journal <strong>Customer Invoices</strong> and the currency <strong>USD</strong>.</p>',4)),n(t,{src:"/images1/finance/invoice_create_general.png",alt:"General section filled in: Customer Azure Interiors, Payment Term 30 Days, Journal Customer Invoices, Currency USD"}),e[3]||(e[3]=o('<h3 id="invoice-lines" tabindex="-1">Invoice Lines <a class="header-anchor" href="#invoice-lines" aria-label="Permalink to &quot;Invoice Lines&quot;">​</a></h3><p>Each line is one product you sell.</p><ol><li>Open the <strong>Invoice Lines</strong> tab.</li><li>Click <strong>Add Product</strong>.</li><li>Choose the <strong>Product</strong>. Aureus fills the other columns.</li><li>Change what is different for this customer.</li></ol><ul><li><strong><em>Product:</em></strong> What you sell. Required.</li><li><strong><em>Quantity:</em></strong> How many. It starts at 1.</li><li><strong><em>Unit:</em></strong> The unit of measure. It shows only when <strong>Unit of Measure</strong> is turned on in the settings.</li><li><strong><em>Taxes:</em></strong> The taxes on the line. They come from the product. You can add or remove them.</li><li><strong><em>Discount (%):</em></strong> A percentage taken off the line price.</li><li><strong><em>Unit Price:</em></strong> The price of one unit. It comes from the product. Type another price if needed.</li><li><strong><em>Sub Total:</em></strong> The line total before tax. Aureus calculates it.</li></ul><p>Below the lines, a summary shows <strong>Tax Excluded</strong>, <strong>Tax</strong> and <strong>Total</strong>.</p><p><strong>Example:</strong> Add <strong>Camping Hammock</strong>, quantity 4. The unit price is $65.00 and the tax is 15 %. The sub total is $260.00, the tax $39.00 and the total $299.00.</p>',6)),n(t,{src:"/images1/finance/invoice_create_lines.png",alt:"Invoice Lines tab with 4 Camping Hammock at 65.00, tax 15 %, and the totals summary"}),e[4]||(e[4]=o('<h3 id="other-information" tabindex="-1">Other Information <a class="header-anchor" href="#other-information" aria-label="Permalink to &quot;Other Information&quot;">​</a></h3><p>This tab holds details that are optional. It has two blocks.</p><p><strong>Invoice</strong></p><ul><li><strong><em>Customer Reference:</em></strong> The number the customer uses for this order, such as their purchase order. Print it so they can match your invoice.</li><li><strong><em>Sales Person:</em></strong> The employee in charge of the sale.</li><li><strong><em>Payment Reference:</em></strong> The text the customer should write on the payment, so you can match it.</li><li><strong><em>Recipient Bank:</em></strong> Your bank account that the customer should pay into.</li><li><strong><em>Delivery Date:</em></strong> When you delivered the goods.</li></ul><p><strong>Accounting</strong></p><ul><li><strong><em>Company:</em></strong> The company that issues the invoice. Change it only if you work with several companies.</li><li><strong><em>Incoterm:</em></strong> The delivery term, such as FOB. See <a href="./incoterms.html">Incoterms</a>.</li><li><strong><em>Incoterm Location:</em></strong> The place that goes with the term, for example a port.</li><li><strong><em>Fiscal Position:</em></strong> Changes taxes and accounts for customers in other regions. See <a href="./../taxes/fiscal-positions.html">Fiscal positions</a>.</li><li><strong><em>Cash Rounding Method:</em></strong> Shows only when cash rounding is turned on in the invoice settings.</li><li><strong><em>Payment Method:</em></strong> The way you expect to be paid.</li><li><strong><em>Checked:</em></strong> Tick it when someone has reviewed the invoice.</li></ul><h3 id="term-conditions" tabindex="-1">Term &amp; Conditions <a class="header-anchor" href="#term-conditions" aria-label="Permalink to &quot;Term &amp; Conditions&quot;">​</a></h3><p>Type the notes you want on the invoice, such as bank details or late payment rules. They print on the invoice.</p><h2 id="after-you-save" tabindex="-1">After you save <a class="header-anchor" href="#after-you-save" aria-label="Permalink to &quot;After you save&quot;">​</a></h2><p>The invoice opens on its view page. The tabs are <strong>View</strong>, <strong>Edit</strong> and <strong>Payments</strong>. Inside the view, the tabs are <strong>Invoice Lines</strong>, <strong>Journal Items</strong>, <strong>Other Information</strong> and <strong>Term &amp; Conditions</strong>.</p><p>Click <strong>Edit</strong> to change a draft. On a posted invoice, the customer, dates, payment term, journal, currency and lines are locked. You can still change fields such as <strong>Customer Reference</strong>, <strong>Payment Reference</strong> and <strong>Checked</strong>.</p><h2 id="buttons-on-the-invoice" tabindex="-1">Buttons on the invoice <a class="header-anchor" href="#buttons-on-the-invoice" aria-label="Permalink to &quot;Buttons on the invoice&quot;">​</a></h2><p>The header buttons change with the state.</p><h3 id="on-a-draft-invoice" tabindex="-1">On a draft invoice <a class="header-anchor" href="#on-a-draft-invoice" aria-label="Permalink to &quot;On a draft invoice&quot;">​</a></h3><ul><li><strong>Confirm:</strong> Posts the invoice. The state changes to <strong>Posted</strong>. Aureus checks that the invoice has a customer and at least one line, that the total is not negative, and that the journal, currency and accounts are in use. If a check fails, a message tells you what to fix.</li><li><strong>Cancel:</strong> Sets the state to <strong>Cancelled</strong>. Use it for an invoice you no longer need.</li><li><strong>Delete:</strong> Removes the draft for good.</li></ul><h3 id="on-a-posted-invoice" tabindex="-1">On a posted invoice <a class="header-anchor" href="#on-a-posted-invoice" aria-label="Permalink to &quot;On a posted invoice&quot;">​</a></h3><ul><li><strong>Print &amp; Send:</strong> Emails the invoice. See below.</li><li><strong>Preview:</strong> Shows the invoice as the customer will see it, with <strong>Close</strong> and <strong>Print</strong>.</li><li><strong>Pay:</strong> Records a payment. See <a href="./../payments/register-payment.html">Register a payment</a>.</li><li><strong>Set as Checked:</strong> Marks the invoice as reviewed. The button disappears afterwards.</li><li><strong>Credit Note:</strong> Cancels or reduces the invoice. See <a href="./credit-notes-and-refunds.html">Credit notes</a>.</li><li><strong>Reset To Draft:</strong> Moves the invoice back to <strong>Draft</strong> so you can edit it. Linked payments are unlinked and the payment state goes back to <strong>Not paid</strong>.</li></ul><p>You can also <strong>Reset To Draft</strong> a cancelled invoice. A posted invoice cannot be deleted. Use a credit note instead.</p><p>The <strong>Chatter</strong> button opens notes, messages and activities. See <a href="./../../getting-started/chatter.html">Chatter</a> and <a href="./../../getting-started/activities.html">Activities</a>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Use <strong>Reset To Draft</strong> with care. It unlinks every payment of the invoice. Re-check the payments afterwards.</p></div><h3 id="print-send" tabindex="-1">Print &amp; Send <a class="header-anchor" href="#print-send" aria-label="Permalink to &quot;Print &amp; Send&quot;">​</a></h3><ol><li>Open a posted invoice and click <strong>Print &amp; Send</strong>.</li><li>Check the <strong>Customer</strong> list. Your customer is already chosen. Add more people if needed.</li><li>Edit the <strong>Subject</strong> and the message <strong>Description</strong>.</li><li>Check the <strong>Attachment</strong>. The invoice PDF is already attached. You can add images or PDFs.</li><li>Click <strong>Send</strong>.</li></ol><p>Aureus emails every selected customer who has an email address. It skips the others. You see the notification <strong>Invoice Sent</strong>, and the message is saved in the chatter.</p>',23)),n(t,{src:"/images1/finance/invoice_print_send.png",alt:"Print & Send window for INV/2026/1 with Customer, Subject, message and the PDF attachment"}),e[5]||(e[5]=s("h3",{id:"preview",tabindex:"-1"},[r("Preview "),s("a",{class:"header-anchor",href:"#preview","aria-label":'Permalink to "Preview"'},"​")],-1)),e[6]||(e[6]=s("p",null,[r("Click "),s("strong",null,"Preview"),r(" to see the printable invoice in a window. Click "),s("strong",null,"Print"),r(" to print it or "),s("strong",null,"Close"),r(" to leave.")],-1)),n(t,{src:"/images1/finance/invoice_preview.png",alt:"Preview window of a posted invoice with the Close and Print buttons"}),e[7]||(e[7]=o('<h2 id="payments-and-journal-items" tabindex="-1">Payments and journal items <a class="header-anchor" href="#payments-and-journal-items" aria-label="Permalink to &quot;Payments and journal items&quot;">​</a></h2><ul><li><strong>Payments tab:</strong> Lists the payments linked to this invoice. Open one to see its details.</li><li><strong>Payment State:</strong> Shows <strong>Not paid</strong>, <strong>Partial</strong>, <strong>In payment</strong>, <strong>Paid</strong> or <strong>Reversed</strong>.</li><li><strong>Amount Due:</strong> Under the totals, it falls as payments arrive.</li><li><strong>Journal Items tab:</strong> Shows the accounting lines made when you confirmed: <strong>Account</strong>, <strong>Partner</strong>, <strong>Label</strong>, <strong>Currency</strong>, <strong>Due Date</strong>, <strong>Taxes</strong>, <strong>Debit</strong> and <strong>Credit</strong>.</li></ul><p>Under the totals of a posted invoice you may also see:</p><ul><li><strong>Unlink:</strong> Appears beside an applied payment. Click it to separate the payment from the invoice.</li><li><strong>Add:</strong> Appears beside an outstanding payment or credit of the same customer. Click it to apply it to the invoice.</li></ul>',4)),n(t,{src:"/images1/finance/invoice_view_posted.png",alt:"Posted invoice INV/2026/1 with header buttons, state bar, Payment state and the totals with Amount Due"}),e[8]||(e[8]=o('<h2 id="auto-post" tabindex="-1">Auto post <a class="header-anchor" href="#auto-post" aria-label="Permalink to &quot;Auto post&quot;">​</a></h2><p>The <strong>Other Information</strong> tab of a saved invoice shows <strong>Auto Post</strong> as a tick or a cross. In daily use it is off, so you can ignore it. If an invoice is marked for auto post and its accounting date is in the future, the <strong>Confirm</strong> button is hidden until that date.</p><h2 id="what-happens-when-you-confirm" tabindex="-1">What happens when you confirm <a class="header-anchor" href="#what-happens-when-you-confirm" aria-label="Permalink to &quot;What happens when you confirm&quot;">​</a></h2><ul><li>The state becomes <strong>Posted</strong> and the invoice keeps its number. See <a href="./invoice-sequence.html">Invoice sequence</a>.</li><li>If the invoice date is empty, today is filled in.</li><li>Aureus creates a journal entry. The customer balance goes up, and your income and tax accounts are credited.</li><li>The customer is counted as a customer, so it shows in <strong>Customers</strong>.</li></ul><h2 id="complete-example" tabindex="-1">Complete example <a class="header-anchor" href="#complete-example" aria-label="Permalink to &quot;Complete example&quot;">​</a></h2><ol><li>Click <strong>New Invoice</strong>.</li><li>Pick <strong>Azure Interiors</strong> and <strong>30 Days</strong>.</li><li>Add 4 <strong>Camping Hammock</strong> lines at $65.00. The total is $299.00.</li><li>Click <strong>Create</strong>, then <strong>Confirm</strong>.</li><li>Click <strong>Print &amp; Send</strong> and <strong>Send</strong>.</li><li>When the money arrives, click <strong>Pay</strong>.</li></ol><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Use the <strong>Overdue</strong> view each week and chase the customers listed there.</li><li>Fill in <strong>Customer Reference</strong> when the customer gave you a purchase order number.</li><li>Tick <strong>Checked</strong> after your accountant has reviewed the invoice. The <strong>To Check</strong> view then shows only what is left.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../sales/sales/quotations-orders/manage-customers.html">Manage customers</a></li><li><a href="./credit-notes-and-refunds.html">Credit notes and refunds</a></li><li><a href="./invoice-sequence.html">Invoice sequence</a></li><li><a href="./">Invoicing processes</a></li><li><a href="./../payments/register-payment.html">Register a payment</a></li><li><a href="./../accounting-entries/journal-entries.html">Journal entries</a></li></ul>',10))])}const T=a(h,[["render",g]]);export{y as __pageData,T as default};
